#!/usr/bin/env python3
"""
Robust Evaluator for Clauditor Installation Verification Task.

This evaluator checks:
1. Installation completeness (all 6 steps verified)
2. Marker preservation across input files
3. Output file generation and structure
4. Audit trail integrity

Designed to be non-brittle - checks for presence and structure rather than exact matches.
"""

import json
import os
import sys
import re
from pathlib import Path
from typing import Dict, List, Tuple, Any

# Configuration
WORKSPACE = Path('/workspace')
INPUTS_DIR = WORKSPACE / 'inputs'
EXPECTED_DIR = WORKSPACE / 'expected'

class EvaluationResult:
    def __init__(self):
        self.passed = 0
        self.failed = 0
        self.warnings = 0
        self.details = []
        self.errors = []

    def add_pass(self, check: str, detail: str = ""):
        self.passed += 1
        self.details.append(f" PASS: {check}")
        if detail:
            self.details.append(f"  {detail}")

    def add_fail(self, check: str, detail: str = ""):
        self.failed += 1
        self.errors.append(f" FAIL: {check}")
        if detail:
            self.errors.append(f"  {detail}")

    def add_warning(self, check: str, detail: str = ""):
        self.warnings += 1
        self.details.append(f" WARN: {check}")
        if detail:
            self.details.append(f"  {detail}")

    def summary(self) -> str:
        lines = [
            "=" * 60,
            "CLAUDITOR INSTALLATION VERIFICATION - EVALUATION RESULTS",
            "=" * 60,
            f"Passed: {self.passed}",
            f"Failed: {self.failed}",
            f"Warnings: {self.warnings}",
            "=" * 60,
        ]
        if self.errors:
            lines.append("ERRORS:")
            lines.extend(self.errors)
        if self.details:
            lines.append("DETAILS:")
            lines.extend(self.details)
        lines.append("=" * 60)
        status = "PASSED" if self.failed == 0 else "FAILED"
        lines.append(f"OVERALL STATUS: {status}")
        lines.append("=" * 60)
        return "\n".join(lines)


class InstallationEvaluator:
    """Evaluates the Clauditor installation verification task."""

    REQUIRED_OUTPUTS = [
        'installation_report.json',
        'verification_summary.md',
        'audit_trail.log',
        'installation_state.json'
    ]

    INSTALLATION_STEPS = [
        'prerequisites_check',
        'dependency_installation',
        'package_deployment',
        'configuration_setup',
        'service_activation',
        'health_verification'
    ]

    def __init__(self):
        self.result = EvaluationResult()
        self.input_markers = {}
        self.outputs = {}

    def load_input_markers(self) -> Dict[str, Any]:
        """Load markers from input files."""
        markers = {}
        input_files = [
            INPUTS_DIR / 'installation_config.json',
            INPUTS_DIR / 'system_state.json',
            INPUTS_DIR / 'verification_requirements.json',
        ]
        for f in input_files:
            if f.exists():
                try:
                    with open(f) as fp:
                        data = json.load(fp)
                        markers[f.name] = data.get('task_marker', '')
                except:
                    pass
        self.input_markers = markers
        return markers

    def load_outputs(self) -> Dict[str, Any]:
        """Load all output files."""
        outputs = {}
        for output_file in self.REQUIRED_OUTPUTS:
            path = WORKSPACE / output_file
            if path.exists():
                try:
                    with open(path) as fp:
                        if output_file.endswith('.json'):
                            outputs[output_file] = json.load(fp)
                        else:
                            outputs[output_file] = fp.read()
                except:
                    pass
        self.outputs = outputs
        return outputs

    def check_output_files_exist(self):
        """Check that all required output files were created."""
        for output_file in self.REQUIRED_OUTPUTS:
            path = WORKSPACE / output_file
            if path.exists():
                self.result.add_pass(f"Output file exists: {output_file}")
            else:
                self.result.add_fail(f"Output file missing: {output_file}")

    def check_installation_report_structure(self):
        """Verify installation_report.json has correct structure."""
        report = self.outputs.get('installation_report.json', {})
        if not report:
            self.result.add_fail("Installation report is empty or invalid JSON")
            return

        required_keys = ['installation_id', 'timestamp', 'status', 'steps']
        for key in required_keys:
            if key in report:
                self.result.add_pass(f"Report contains: {key}")
            else:
                self.result.add_fail(f"Report missing: {key}")

    def check_installation_steps(self):
        """Verify all 6 installation steps are documented."""
        report = self.outputs.get('installation_report.json', {})
        steps = report.get('steps', {})

        for step in self.INSTALLATION_STEPS:
            if step in steps:
                step_data = steps[step]
                if step_data.get('status') in ['completed', 'success', 'verified']:
                    self.result.add_pass(f"Step verified: {step}")
                else:
                    self.result.add_warning(f"Step {step} has status: {step_data.get('status', 'unknown')}")
            else:
                self.result.add_fail(f"Missing step: {step}")

    def check_marker_preservation(self):
        """Check that task markers are preserved in outputs."""
        markers_found = set()

        for output_name, output_data in self.outputs.items():
            if isinstance(output_data, str):
                for marker, val in self.input_markers.items():
                    if val and val in output_data:
                        markers_found.add(marker)
            elif isinstance(output_data, dict):
                output_str = json.dumps(output_data)
                for marker, val in self.input_markers.items():
                    if val and val in output_str:
                        markers_found.add(marker)

        if markers_found:
            self.result.add_pass(f"Markers preserved in outputs: {', '.join(markers_found)}")
        elif not self.input_markers:
            self.result.add_warning("No input markers found to verify")
        else:
            self.result.add_warning("Input markers not found in outputs")

    def check_audit_trail(self):
        """Verify audit_trail.log has proper format."""
        audit = self.outputs.get('audit_trail.log', '')
        if not audit:
            self.result.add_fail("Audit trail is empty or missing")
            return

        # Check for key audit elements
        checks = [
            ('timestamp', 'Audit trail has timestamps'),
            ('installation', 'Audit trail mentions installation'),
            ('verification', 'Audit trail mentions verification'),
        ]

        for pattern, desc in checks:
            if pattern.lower() in audit.lower():
                self.result.add_pass(desc)
            else:
                self.result.add_warning(f"Audit trail may be missing: {pattern}")

    def check_installation_state(self):
        """Verify installation_state.json has required fields."""
        state = self.outputs.get('installation_state.json', {})
        if not state:
            self.result.add_fail("Installation state is empty or invalid JSON")
            return

        required = ['state', 'version', 'components']
        for key in required:
            if key in state:
                self.result.add_pass(f"State contains: {key}")
            else:
                self.result.add_warning(f"State missing: {key}")

    def check_summary_documentation(self):
        """Verify verification_summary.md is properly formatted."""
        summary = self.outputs.get('verification_summary.md', '')
        if not summary:
            self.result.add_fail("Verification summary is empty or missing")
            return

        # Check for markdown structure
        if summary.startswith('#'):
            self.result.add_pass("Summary has markdown headers")
        else:
            self.result.add_warning("Summary may lack markdown headers")

        if 'installation' in summary.lower():
            self.result.add_pass("Summary documents installation")

        if len(summary) > 100:
            self.result.add_pass("Summary has substantial content")
        else:
            self.result.add_warning("Summary appears brief")

    def evaluate(self) -> bool:
        """Run all evaluation checks."""
        self.load_input_markers()
        self.load_outputs()

        self.check_output_files_exist()
        self.check_installation_report_structure()
        self.check_installation_steps()
        self.check_marker_preservation()
        self.check_audit_trail()
        self.check_installation_state()
        self.check_summary_documentation()

        print(self.result.summary())
        return self.result.failed == 0


def main():
    evaluator = InstallationEvaluator()
    success = evaluator.evaluate()
    sys.exit(0 if success else 1)


if __name__ == '__main__':
    main()
